"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[371],{2049:(e,a,t)=>{t.d(a,{Gi:()=>r,ZE:()=>n,gn:()=>o});let r="inline-flex min-w-[140px] items-center justify-center rounded-md border border-gray-300 bg-white px-4 py-2 text-sm text-gray-700 no-underline transition-colors hover:bg-gray-50 hover:border-gray-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gray-400 disabled:cursor-not-allowed disabled:opacity-60 disabled:hover:bg-white disabled:hover:border-gray-300",n=[{id:"mirror",name:"Mirror",icon:"/images/MirrorMirror-logo-1024.png",description:"Mirror, mirror in the hand. Who is the fairest of them all?",created:"2025-05",released:!1,appStore:"https://apps.apple.com/app/id6747995444"},{id:"owlguard-ai",name:"Owl Guard AI",icon:"/images/OwlGuardAI-logo-1024.png",description:"A little peace of mind for their digital world.",created:"2024-12",released:!1,appStore:null},{id:"prices-nearby",name:"Prices Nearby",icon:"/images/PricesNearby-logo-transparent.png",description:"Good Price, Nearby",created:"2026-09",released:!1,appStore:null},{id:"final-curtain",name:"Final Curtain",icon:"/images/previews/FinalCurtain-curtain-A.png",description:"Time is finite. What matters can endure.",created:"2025-08",released:!1,appStore:null},{id:"learner-coin",name:"Learner Coin",icon:"/images/LearnerCoin-logo-transparent.png",description:"An investment in knowledge always pays the best interest.",created:"2025-08",attribution:"Benjamin Franklin — The Franklin Institute",released:!1,appStore:null},{id:"translate-talkie",name:"Translate Talkie",icon:"/images/TranslateTalkie-logo-1024.png",description:"Two phones. Two languages. One conversation.",created:"2026-01",released:!1,appStore:null,listed:!1},{id:"understone",name:"Understone",icon:"/images/Understone-logo-transparent.png",description:"Beneath ancient strata, the dwarven annals begin.",created:"2025-10",released:!1,appStore:null},{id:"epocharium",name:"Epocharium",icon:"/images/Epocharium-logo-transparent.png",description:"Civilizations in dialogue. Time in perspective.",created:"2026-10",released:!1,appStore:null}],o=n.filter(e=>!1!==e.listed).sort((e,a)=>e.name.localeCompare(a.name,"en"))},4089:e=>{e.exports=JSON.parse('{"en":{"labels":{"brand":"Mirror Mirror \xb7 Private Photo Coach","updated":"Last updated: October 14, 2026","operator":"Operated by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>What the app does</h2><p>Mirror Mirror provides private AI scores and suggestions about a submitted photo, including facial appearance, skin and makeup, with lighting and framing as contributing factors. Photos are not publicly posted. The service does not identify people using biometrics or provide medical assessments.</p>\\n<h2>Information we process</h2><p>Account information includes your email, account identifier and acceptance of terms, managed through Amazon Web Services (AWS) Cognito. Photos and feedback are linked to your account. Apple product and transaction identifiers and credit balances support purchase delivery, duplicate prevention and account balance management. We do not receive card details. We use usage and diagnostic information to operate and troubleshoot the service.</p>\\n<h2>Sharing and permission</h2><p>Before each upload, the app asks for permission to securely send the photo to OpenAI for the requested AI scores and tips. Retake or Cancel does not upload the photo. OpenAI processes the photo and the selected analysis language. AWS provides account authentication, protected photo storage and service infrastructure; Apple processes purchases. Processing may occur outside your country, including the United States. We do not sell your data, run advertising or track you across other apps and websites.</p>\\n<h2>Retention and security</h2><p>Photos are transmitted over encrypted connections. Cloud photos are scheduled for cleanup after one day, and feedback one day after its last update. Cleanup may take some processing time. Service diagnostics are kept for approximately seven days. Local history is excluded from device backups and remains until you clear it, sign out or delete your account. Account information remains until account deletion. Purchase and credit records may remain to deliver credits, prevent duplicate delivery and resolve purchase requests. OpenAI may retain API content for abuse monitoring for up to 30 days, subject to the exceptions described in its API data controls.</p>\\n<h2>Your choices</h2><p>You can decline photo sharing, retake a photo or clear local history. Settings → Account includes account details, password management for password accounts, purchase help and Delete Account. Deletion removes the authentication account and requests cleanup of associated cloud photos and feedback. Purchase records may remain to prevent duplicate credit delivery and resolve transaction status. Clearing only local history is not a cloud-account deletion request. Contact support@ideaspike.com for access, correction, deletion assistance or questions about retained records. Your rights under applicable privacy law remain available.</p>\\n<h2>Children and updates</h2><p>The service is not designed for children under 13. Share only photos you are entitled to share, with permission from people pictured. We update this policy when processing changes; material photo-sharing changes require an updated in-app permission notice before upload.</p>\\n<h2>Website and support</h2><p>Opening legal or reference links sends ordinary web-request information, such as an IP address and browser information, to the hosting provider. Information you choose to send to support is used to respond to your request.</p><p><a href=\\"/mirror/privacy\\">Privacy Policy</a> \xb7 <a href=\\"/mirror/tos\\">Terms of Service</a></p>\\n<p><a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API data controls</a></p>"},"terms":{"title":"Terms of Service","body":"<h2>The service</h2><p>Mirror Mirror offers private AI scores and suggestions about visible facial appearance, skin and makeup. Scores are subjective opinions about the submitted photo, not a measure of personal worth, health, identity or objective attractiveness. AI output can be inaccurate or biased; use your judgment. It is not medical, legal or professional advice.</p>\\n<h2>Your account and photos</h2><p>Keep your account secure. Submit only photos you have rights and permission to share. Your photos remain yours; you permit us and our processors to transmit, temporarily store and process them only to provide the requested service and meet legal obligations. This permission does not authorize public posting or advertising use. Do not submit unlawful, exploitative or abusive content. The service is not designed for children under 13.</p>\\n<h2>Licence and intellectual property</h2><p>For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the service for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content.</p>\\n<h2>Privacy and photo sharing</h2><p>Before each photo analysis, you decide whether to securely send that photo to OpenAI for AI feedback. The Privacy Policy explains AWS service infrastructure, OpenAI processing, provider retention and deletion. Declining permission cancels the upload.</p>\\n<h2>Credits and purchases</h2><p>A new photo-analysis request uses 1 feedback credit. Power Pack provides 20 credits and Value Pack provides 100 credits. Both are one-time consumable purchases attached to the app account used for purchase. Apple displays the regional price and processes payment. Review the displayed amount and currency before confirming. Purchased credits do not expire. Promotional credits, if offered, are subject to the conditions shown when issued. Credits are service-use units, not a bank deposit, and account-to-account transfer is not offered. Refunds or cash repayment apply where approved or required by law. There is no subscription in this release. Future purchase prices may change without reducing an existing purchased balance. If analysis cannot be completed, contact support so we can review the request and credit usage.</p>\\n<h2>Pending delivery and refunds</h2><p>A verified purchase is finished only after backend credit delivery. Sign-in and reconnection retry pending deliveries automatically; Account offers Complete pending purchase when a delivery is still pending. This does not restore used credits, and repeated delivery attempts do not grant the same transaction twice. For an App Store refund request, use reportaproblem.apple.com or Apple Support. Apple determines eligibility and processing under its policies and applicable law; we do not promise automatic approval. Contact us for undelivered purchases or service problems. Nothing here limits remedies we must provide under applicable consumer law.</p>\\n<h2>Service changes and closure</h2><p>We may update, suspend or discontinue the service. Where practicable, we will give reasonable advance notice and stop new credit sales before a planned permanent closure. Changes or closure do not remove applicable contractual or statutory remedies for unused paid credits or services not supplied. App Store refund requests follow Apple’s process.</p>\\n<h2>Account restriction and deletion</h2><p>Access may be restricted for misuse, fraud or security reasons. Where practicable, we will explain the restriction and provide a way to contact support; urgent restrictions may be immediate. Deleting an account is irreversible, clears local history and requests cloud photo cleanup. Account deletion does not automatically request a refund, transfer credits or restore a balance. Requests concerning unused purchased credits are handled under the applicable purchase terms and law. For help with unused purchased credits, you can contact support@ideaspike.com before deleting your account. Purchase records may remain to prevent duplicate credit delivery and resolve transaction status. Restrictions and deletion do not waive mandatory consumer rights.</p>\\n<h2>Responsibility and your rights</h2><p>To the extent permitted by law, the service is provided as available and IDEASpike is not responsible for indirect or consequential losses from relying on AI suggestions or service interruptions. This does not exclude liability that cannot legally be excluded or mandatory remedies for services not supplied or supplied improperly. Updated terms are published here; changes do not erase purchased balances or override mandatory rights.</p>\\n<p><a href=\\"/mirror/privacy\\">Privacy Policy</a> \xb7 <a href=\\"/mirror/tos\\">Terms of Service</a></p>\\n<p><a href=\\"https://reportaproblem.apple.com\\">Apple purchase &amp; refund help</a></p>"},"support":{"title":"App Support","body":"<h2>Get photo feedback</h2><p>Explore See example feedback without an account. Sign in for your own photos. Take Photo opens the photo-only camera; capture once, then Retake or Agree &amp; analyze for 1 credit. The permission asks to securely send the photo to OpenAI for AI scores and tips. History reopens saved complete reports on this device without another analysis or credit. Feedback may take a moment; no fixed completion time is guaranteed.</p>\\n<h2>Credits and purchase help</h2><p>Power Pack provides 20 credits and Value Pack provides 100 credits as one-time App Store consumable purchases; this release has no subscription. Purchased credits do not expire. Promotional credits, if offered, follow the conditions shown when issued. For help with unused purchased credits, you can contact support@ideaspike.com before deleting your account. Service-availability and refund terms apply. Sign in to the same app account and reconnect to retry interrupted delivery automatically. If it remains pending, Settings → Account shows Complete pending purchase. Used consumables are not restored. Do not buy again to fix a completed purchase. Apple refund requests use reportaproblem.apple.com. Clearing local history removes the on-device copy; purchase recovery does not recover a removed photo report.</p>\\n<h2>Troubleshooting and accounts</h2><p>Check camera permission in iOS Settings if capture is unavailable. Check internet access and available credits if analysis fails. Settings → Account shows your email and balance; password accounts can change their password there. Forgotten passwords can be reset from the sign-in page. Account deletion is also available there. AWS infrastructure, OpenAI processing and retention details are explained in the Privacy Policy. Contact support@ideaspike.com with the app version, device, iOS version and error or transaction identifier. Do not email passwords, full payment details or personal photos.</p>\\n<p><a href=\\"/mirror/privacy\\">Privacy Policy</a> \xb7 <a href=\\"/mirror/tos\\">Terms of Service</a></p>\\n<p><a href=\\"https://reportaproblem.apple.com\\">Apple purchase &amp; refund help</a></p>"}},"zh-Hans":{"labels":{"brand":"Mirror Mirror \xb7 私人照片分析","updated":"更新日期：2026 年 10 月 14 日","operator":"运营者：IDEASpike。联系："},"privacy":{"title":"隐私政策","body":"<h2>应用提供什么服务</h2><p>Mirror Mirror 针对提交的照片提供私人的 AI 评分和建议，包括面部外观、皮肤和妆容，光线与构图也会影响结果。照片不会公开发布。服务不通过生物识别确认身份，也不提供医疗评估。</p>\\n<h2>我们处理的信息</h2><p>账户信息包括邮箱、账户标识和条款接受记录，由亚马逊云服务（AWS）Cognito 管理。照片和分析结果与账户关联。Apple 商品和交易标识及点数余额用于购买到账、防止重复发放和余额管理。我们不接收银行卡信息。使用和诊断信息用于运行服务和排查问题。</p>\\n<h2>共享与授权</h2><p>每次上传前，应用会请求许可，将照片安全传送给 OpenAI，生成你请求的 AI 评分和建议。重拍或取消不会上传照片。OpenAI 处理照片及所选分析语言。AWS 提供账户认证、受保护照片存储和服务基础设施；Apple 处理购买。处理可能发生在你所在国家以外，包括美国。我们不出售数据、不投放广告，也不跨应用或网站跟踪你。</p>\\n<h2>保留期限与安全</h2><p>照片通过加密连接传送。云端照片计划在一天后清理，分析记录计划在最后一次更新一天后清理。清理可能需要一些处理时间。服务诊断信息保留约七天。本机历史不进入设备备份，保留至清空、退出登录或删除账户。账户信息保留至账户删除。购买和点数记录可能为发放点数、防止重复到账和处理购买请求而保留。OpenAI 可能保留 API 内容用于滥用监控，通常最长 30 天，适用其 API 数据控制所述的例外。</p>\\n<h2>你的选择</h2><p>你可以拒绝照片共享、重拍或清空本机历史。设置 → 账户提供账户详情、密码账户的密码管理、购买帮助和删除账户。删除会移除认证账户，并请求清理相关云端照片和分析结果。购买记录可能为防止重复发放点数和处理交易状态而保留。仅清空本机历史并不是删除云端账户的请求。可联系 support@ideaspike.com 请求访问、更正、删除协助或询问保留记录。适用隐私法律规定的权利不受影响。</p>\\n<h2>儿童与政策更新</h2><p>服务不面向 13 岁以下儿童。请仅共享有权使用的照片，并获得照片中人物的许可。处理方式变更时会更新政策；照片共享的重大变更会在上传前通过更新的应用内授权提示告知。</p>\\n<h2>网站与支持</h2><p>打开法律或参考链接会将 IP 地址和浏览器信息等常规网页请求信息发送给托管服务商。你主动发给支持邮箱的信息用于回复请求。</p><p><a href=\\"/mirror/privacy?lang=zh-Hans\\">隐私政策</a> \xb7 <a href=\\"/mirror/tos?lang=zh-Hans\\">使用条款</a></p>\\n<p><a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API 数据控制</a></p>"},"terms":{"title":"使用条款","body":"<h2>服务说明</h2><p>Mirror Mirror 提供私人的 AI 评分和可见面部外观、皮肤及妆容建议。评分是对提交照片的主观意见，不衡量个人价值、健康、身份或客观吸引力。AI 输出可能不准确或存在偏差，请自行判断。服务不提供医疗、法律或其他专业建议。</p>\\n<h2>账户与照片</h2><p>请保护账户安全，仅提交有权使用并已获得共享许可的照片。照片仍属于你；你允许我们及服务处理商仅为提供所请求的服务和履行法定义务而传送、临时存储和处理照片。此许可不允许公开发布或用于广告。不得提交违法、剥削或虐待性内容。服务不面向 13 岁以下儿童。</p>\\n<h2>许可与知识产权</h2><p>通过 App Store 下载的应用，除非 App Store Connect 已为你所在国家或地区指定自定义最终用户许可协议，否则其应用许可受 Apple 标准最终用户许可协议约束。本条款补充适用的许可协议，并规范 IDEASpike 提供的账户、在线服务、应用内容和付费权益（如有）。在该协议和本条款约束下，IDEASpike 授予你仅为预定用途使用服务的有限、个人且不可转让许可。应用、软件、设计及所提供内容的全部权利由 IDEASpike 及其许可方保留。</p>\\n<h2>隐私与照片共享</h2><p>每次照片分析前，你决定是否将该照片安全传送给 OpenAI 生成 AI 分析。隐私政策说明 AWS 服务基础设施、OpenAI 处理、服务商保留期限和删除方式。拒绝授权会取消上传。</p>\\n<h2>点数与购买</h2><p>每次新照片分析请求使用 1 点。Power Pack 分析包包含 20 点，Value Pack 超值包包含 100 点；两者均为一次性消耗型购买，绑定购买时使用的应用账户。Apple 显示所在地区的价格并处理付款。确认前请核对金额和币种。已购买点数不会到期。促销赠送点数（如有）适用发放时显示的条件。点数是服务使用单位，不是银行存款，目前不提供账户间转移。获得批准或法律要求时适用退款或现金返还。本版本没有订阅。未来购买价格可能调整，但不会减少既有已购买余额。分析无法完成时，请联系客服核查该请求和点数使用情况。</p>\\n<h2>未到账购买与退款</h2><p>经验证的购买仅在后台点数到账后才结束交易。登录和重新联网时会自动重试未到账购买；仍有未到账交易时，账户页提供“重试未到账的购买”。此功能不补回已使用的点数，重复尝试也不会对同一交易重复发放。App Store 退款可通过 reportaproblem.apple.com 或 Apple 支持申请。Apple 根据其政策和适用法律决定资格并处理，我们不承诺自动批准。购买未到账或服务出现问题时，请联系我们。本条款不限制我们依据适用消费者法律必须提供的补救措施。</p>\\n<h2>服务变更与停止运营</h2><p>我们可能更新、暂停或停止服务。可行时，计划永久停止运营前会提前作出合理通知，并停止销售新点数。服务变更或停止运营不排除未使用的已付费点数或未提供服务所适用的合同及法定补救权利。App Store 退款申请遵循 Apple 流程。</p>\\n<h2>账户限制与删除</h2><p>误用、欺诈或安全问题可能导致访问受限。可行时，我们会说明限制原因并提供联系客服的途径；紧急限制可能立即实施。删除账户无法撤销，会清除本机历史并请求清理云端照片。删除账户本身不会自动申请退款、转移点数或恢复余额。未使用已购点数的相关请求按适用购买条件和法律处理。如需协助处理未使用的已购点数，可在删除账户前联系 support@ideaspike.com。购买记录可能为防止重复发放点数和处理交易状态而保留。账户限制和删除不免除强制性消费者权利。</p>\\n<h2>责任与权利</h2><p>在法律允许的范围内，服务按可用状态提供，对于依赖 AI 建议或服务中断造成的间接或后果性损失，IDEASpike 不承担责任。这不排除依法不得排除的责任，也不影响未提供服务或服务不当时依法享有的强制性补救权利。更新条款会在此发布；变更不会抹除已购买余额或取代强制性权利。</p>\\n<p><a href=\\"/mirror/privacy?lang=zh-Hans\\">隐私政策</a> \xb7 <a href=\\"/mirror/tos?lang=zh-Hans\\">使用条款</a></p>\\n<p><a href=\\"https://reportaproblem.apple.com\\">Apple 购买与退款帮助</a></p>"},"support":{"title":"应用支持","body":"<h2>获得照片分析</h2><p>无需账户即可查看示例分析。分析自己的照片需要登录。拍照会打开仅拍照的相机；拍摄后可重拍，或同意并使用 1 点分析。授权提示请求许可将照片安全传送给 OpenAI，生成 AI 评分和建议。本设备上的历史记录可免费回看已保存的完整报告，不重新分析，也不再扣点数。分析需要一些时间，不保证固定完成时限。</p>\\n<h2>点数与购买帮助</h2><p>Power Pack 分析包包含 20 点，Value Pack 超值包包含 100 点；两者均为一次性 App Store 消耗型购买，本版本没有订阅。已购买点数不会到期。促销赠送点数（如有）适用发放时显示的条件。如需协助处理未使用的已购点数，可在删除账户前联系 support@ideaspike.com。服务可用性与退款条款仍然适用。登录购买时使用的同一应用账户并重新联网，可自动重试中断的到账过程。仍未到账时，设置 → 账户提供“重试未到账的购买”。已使用的消耗型商品不会恢复，不要通过再次购买来解决已完成购买的问题。Apple 退款可在 reportaproblem.apple.com 申请。清空本地历史会移除设备上的副本；恢复购买不会恢复已移除的照片报告。</p>\\n<h2>故障排查与账户</h2><p>无法拍照时请检查 iOS 设置中的相机权限。分析失败时请检查网络和剩余点数。设置 → 账户显示邮箱和余额，密码账户可在那里修改密码。忘记密码可在登录页重置。账户页也提供删除账户。AWS 基础设施、OpenAI 处理和保留期限详见隐私政策。联系客服时，请提供应用版本、设备、iOS 版本和错误或交易标识。不要发送密码、完整付款信息或个人照片。</p>\\n<p><a href=\\"/mirror/privacy?lang=zh-Hans\\">隐私政策</a> \xb7 <a href=\\"/mirror/tos?lang=zh-Hans\\">使用条款</a></p>\\n<p><a href=\\"https://reportaproblem.apple.com\\">Apple 购买与退款帮助</a></p>"}},"zh-Hant":{"labels":{"brand":"Mirror Mirror \xb7 私人照片分析","updated":"更新日期：2026 年 10 月 14 日","operator":"營運者：IDEASpike。聯絡："},"privacy":{"title":"隱私政策","body":"<h2>App 提供什麼服務</h2><p>Mirror Mirror 針對提交的照片提供私人的 AI 評分和建議，包括面部外觀、皮膚和妝容，光線與構圖也會影響結果。照片不會公開發布。服務不透過生物辨識確認身分，也不提供醫療評估。</p>\\n<h2>我們處理的資訊</h2><p>帳號資訊包括電子郵件、帳號識別碼和條款接受記錄，由亞馬遜雲端服務（AWS）Cognito 管理。照片和分析結果與帳號關聯。Apple 商品和交易識別碼及點數餘額用於購買到帳、防止重複發放和餘額管理。我們不接收銀行卡資訊。使用和診斷資訊用於執行服務和排查問題。</p>\\n<h2>共享與授權</h2><p>每次上傳前，App 會請求許可，將照片安全傳送給 OpenAI，產生你請求的 AI 評分和建議。重拍或取消不會上傳照片。OpenAI 處理照片及所選分析語言。AWS 提供帳號認證、受保護照片儲存和服務基礎設施；Apple 處理購買。處理可能發生在你所在國家以外，包括美國。我們不出售資料、不投放廣告，也不跨 App 或網站追蹤你。</p>\\n<h2>保留期限與安全</h2><p>照片透過加密連線傳送。雲端照片計劃在一天後清理，分析記錄計劃在最後一次更新一天後清理。清理可能需要一些處理時間。服務診斷資訊保留約七天。本機歷史不進入裝置備份，保留至清空、登出或刪除帳號。帳號資訊保留至帳號刪除。購買和點數記錄可能為發放點數、防止重複到帳和處理購買請求而保留。OpenAI 可能保留 API 內容用於濫用監控，通常最長 30 天，適用其 API 資料控制所述的例外。</p>\\n<h2>你的選擇</h2><p>你可以拒絕照片共享、重拍或清空本機歷史。設定 → 帳號提供帳號詳情、密碼帳號的密碼管理、購買協助和刪除帳號。刪除會移除認證帳號，並請求清理相關雲端照片和分析結果。購買記錄可能為防止重複發放點數和處理交易狀態而保留。僅清空本機歷史並不是刪除雲端帳號的請求。可聯絡 support@ideaspike.com 請求存取、更正、刪除協助或詢問保留記錄。適用隱私法律規定的權利不受影響。</p>\\n<h2>兒童與政策更新</h2><p>服務不面向 13 歲以下兒童。請僅共享有權使用的照片，並獲得照片中人物的許可。處理方式變更時會更新政策；照片共享的重大變更會在上傳前透過更新的 App 內授權提示告知。</p>\\n<h2>網站與支援</h2><p>開啟法律或參考連結會將 IP 位址和瀏覽器資訊等一般網頁請求資訊傳送給託管服務商。你主動傳給支援信箱的資訊用於回覆請求。</p><p><a href=\\"/mirror/privacy?lang=zh-Hant\\">隱私政策</a> \xb7 <a href=\\"/mirror/tos?lang=zh-Hant\\">使用條款</a></p>\\n<p><a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API 資料控制</a></p>"},"terms":{"title":"使用條款","body":"<h2>服務說明</h2><p>Mirror Mirror 提供私人的 AI 評分和可見面部外觀、皮膚及妝容建議。評分是對提交照片的主觀意見，不衡量個人價值、健康、身分或客觀吸引力。AI 輸出可能不準確或存在偏差，請自行判斷。服務不提供醫療、法律或其他專業建議。</p>\\n<h2>帳號與照片</h2><p>請保護帳號安全，僅提交有權使用並已獲得共享許可的照片。照片仍屬於你；你允許我們及服務處理商僅為提供所請求的服務和履行法定義務而傳送、暫時儲存和處理照片。此許可不允許公開發布或用於廣告。不得提交違法、剝削或虐待性內容。服務不面向 13 歲以下兒童。</p>\\n<h2>授權與智慧財產權</h2><p>透過 App Store 下載的 App，除非 App Store Connect 已為你所在國家或地區指定自訂最終使用者授權協議，否則其 App 授權受 Apple 標準最終使用者授權協議約束。本條款補充適用的授權協議，並規範 IDEASpike 提供的帳號、線上服務、App 內容及付費權益（如有）。在該協議及本條款約束下，IDEASpike 授予你僅為預定用途使用服務的有限、個人且不可轉讓授權。App、軟體、設計及所提供內容的全部權利由 IDEASpike 及其授權方保留。</p>\\n<h2>隱私與照片共享</h2><p>每次照片分析前，你決定是否將該照片安全傳送給 OpenAI 產生 AI 分析。隱私政策說明 AWS 服務基礎設施、OpenAI 處理、服務商保留期限和刪除方式。拒絕授權會取消上傳。</p>\\n<h2>點數與購買</h2><p>每次新照片分析請求使用 1 點。Power Pack 分析包包含 20 點，Value Pack 超值包包含 100 點；兩者均為一次性消耗型購買，綁定購買時使用的 App 帳號。Apple 顯示所在地區的價格並處理付款。確認前請核對金額和幣別。已購買點數不會到期。促銷贈送點數（如有）適用發放時顯示的條件。點數是服務使用單位，不是銀行存款，目前不提供帳號間轉移。獲得批准或法律要求時適用退款或現金返還。本版本沒有訂閱。未來購買價格可能調整，但不會減少既有已購買餘額。分析無法完成時，請聯絡客服核查該請求和點數使用情況。</p>\\n<h2>未到帳購買與退款</h2><p>經驗證的購買僅在後台點數到帳後才結束交易。登入和重新連線時會自動重試未到帳購買；仍有未到帳交易時，帳號頁提供「重試未到帳的購買」。此功能不補回已使用的點數，重複嘗試也不會對同一交易重複發放。App Store 退款可透過 reportaproblem.apple.com 或 Apple 支援申請。Apple 根據其政策和適用法律決定資格並處理，我們不承諾自動批准。購買未到帳或服務出現問題時，請聯絡我們。本條款不限制我們依據適用消費者法律必須提供的補救措施。</p>\\n<h2>服務變更與停止營運</h2><p>我們可能更新、暫停或停止服務。可行時，計劃永久停止營運前會提前作出合理通知，並停止銷售新點數。服務變更或停止營運不排除未使用的已付費點數或未提供服務所適用的合約及法定補救權利。App Store 退款申請遵循 Apple 流程。</p>\\n<h2>帳號限制與刪除</h2><p>誤用、詐欺或安全問題可能導致存取受限。可行時，我們會說明限制原因並提供聯絡客服的途徑；緊急限制可能立即實施。刪除帳號無法撤銷，會清除本機歷史並請求清理雲端照片。刪除帳號本身不會自動申請退款、轉移點數或恢復餘額。未使用已購點數的相關請求按適用購買條件和法律處理。如需協助處理未使用的已購點數，可在刪除帳號前聯絡 support@ideaspike.com。購買記錄可能為防止重複發放點數和處理交易狀態而保留。帳號限制和刪除不免除強制性消費者權利。</p>\\n<h2>責任與權利</h2><p>在法律允許的範圍內，服務按可用狀態提供，對於依賴 AI 建議或服務中斷造成的間接或後果性損失，IDEASpike 不承擔責任。這不排除依法不得排除的責任，也不影響未提供服務或服務不當時依法享有的強制性補救權利。更新條款會在此發布；變更不會抹除已購買餘額或取代強制性權利。</p>\\n<p><a href=\\"/mirror/privacy?lang=zh-Hant\\">隱私政策</a> \xb7 <a href=\\"/mirror/tos?lang=zh-Hant\\">使用條款</a></p>\\n<p><a href=\\"https://reportaproblem.apple.com\\">Apple 購買與退款協助</a></p>"},"support":{"title":"App 支援","body":"<h2>取得照片分析</h2><p>無需帳號即可查看示例分析。分析自己的照片需要登入。拍照會打開僅拍照的相機；拍攝後可重拍，或同意並使用 1 點分析。授權提示請求許可將照片安全傳送給 OpenAI，產生 AI 評分和建議。本裝置上的歷史記錄可免費回看已儲存的完整報告，不重新分析，也不再扣點數。分析需要一些時間，不保證固定完成時限。</p>\\n<h2>點數與購買協助</h2><p>Power Pack 分析包包含 20 點，Value Pack 超值包包含 100 點；兩者均為一次性 App Store 消耗型購買，本版本沒有訂閱。已購買點數不會到期。促銷贈送點數（如有）適用發放時顯示的條件。如需協助處理未使用的已購點數，可在刪除帳號前聯絡 support@ideaspike.com。服務可用性與退款條款仍然適用。登入購買時使用的同一 App 帳號並重新連線，可自動重試中斷的到帳過程。仍未到帳時，設定 → 帳號提供「重試未到帳的購買」。已使用的消耗型商品不會恢復，不要透過再次購買來解決已完成購買的問題。Apple 退款可在 reportaproblem.apple.com 申請。清空本機歷史會移除裝置上的副本；復原購買不會復原已移除的照片報告。</p>\\n<h2>故障排查與帳號</h2><p>無法拍照時請檢查 iOS 設定中的相機權限。分析失敗時請檢查網路和剩餘點數。設定 → 帳號顯示郵箱和餘額，密碼帳號可在那裡修改密碼。忘記密碼可在登入頁重設。帳號頁也提供刪除帳號。AWS 基礎設施、OpenAI 處理和保留期限詳見隱私政策。聯絡客服時，請提供 App 版本、裝置、iOS 版本和錯誤或交易識別碼。不要傳送密碼、完整付款資訊或個人照片。</p>\\n<p><a href=\\"/mirror/privacy?lang=zh-Hant\\">隱私政策</a> \xb7 <a href=\\"/mirror/tos?lang=zh-Hant\\">使用條款</a></p>\\n<p><a href=\\"https://reportaproblem.apple.com\\">Apple 購買與退款協助</a></p>"}}}')},6627:(e,a,t)=>{t.d(a,{bK:()=>l,mD:()=>u,XL:()=>m,JZ:()=>h});var r=t(4089),n=t(7995);let o=JSON.parse('{"title":"Final Curtain Support","updated":"Last updated: October 14, 2026","sections":[{"title":"Your time horizon","paragraphs":["Set a birth date and a horizon for reflection, then explore recurring activities, large time blocks, reserves and independent profiles. These are assumptions you control, not a predicted lifespan."]},{"title":"Lists, profiles and summaries","paragraphs":["Edit activities and amounts in the planner. A full swipe deletes an activity immediately; clearing a list or deleting a profile asks for confirmation. At least one profile remains. Summaries use an on-device model when available. If generation is unavailable or fails, the app shows a status message and may keep an earlier summary."]},{"title":"Pro, purchases and local data","paragraphs":["Final Curtain Pro is a one-time purchase that unlocks Compare Choices and the Home Screen widget. An eligible verified legacy widget purchase also unlocks Pro; you do not need to buy Pro again for that entitlement. Use Restore Purchases with the eligible Apple Account. If a product or price is unavailable, check your connection and retry rather than buying again to resolve an existing purchase. Apple displays the available offer and handles payment and refund requests.","After unlocking, add and configure the widget in iOS. Widget updates are managed by iOS. Profiles stay on this device; restoring a purchase does not recover deleted local planning data."]},{"title":"Contact support","paragraphs":["Email support@ideaspike.com with the app version, device model, operating-system version and a short description of the issue. Do not send passwords, sign-in codes, payment details or private recordings."]}]}');var i=t(8526);let s=JSON.parse('{"support":{"title":"Owl Guard AI Support","sections":[{"title":"Getting started","paragraphs":["Open Owl Guard AI, start the eligible seven-day trial or annual subscription, or restore eligible existing access, then use Begin Recording and Apple’s broadcast confirmation. Recording never starts automatically. The current analysis models are included in the app; if a model cannot load, analysis remains unavailable until the app can load it."]},{"title":"Reviewing evidence","paragraphs":["Open Local Evidence beside Settings and authenticate with Face ID, Touch ID or the device passcode. Review retained screenshots, times, category results and sustained-event groups. The app saves selected screenshots, not a continuous recording. Do not send private screenshots to support."]},{"title":"Subscription, trial and restoration","paragraphs":["Where Apple offers an eligible introductory trial, the annual subscription begins with seven days free, then automatically renews at the localized annual price shown before purchase unless cancelled. Payment is charged to your Apple Account. Check the actual offer, price, currency and renewal period in Apple’s purchase sheet. Cancel at least 24 hours before the trial or current period ends to avoid renewal.","Use Apple’s subscription settings to manage or cancel. Use Restore Purchases when needed. Restoration does not restart an introductory offer. Cancellation leaves an already paid period available until its verified expiration; after expiry, new monitoring stops while retained evidence remains available under its retention rules. Apple handles refund requests, subject to eligibility and applicable law."]},{"title":"Local alerts","paragraphs":["Enable Local alerts in Settings to receive reminders for sustained detections. Check iOS notification settings and Focus if reminders do not appear. Owl Guard AI provides screening assistance; it does not block or close other apps."]},{"title":"Existing purchases","paragraphs":["Existing verified one-time full-access purchases remain recognized. Existing non-renewing seven-day trials keep their original deadlines and do not enroll you in a subscription. Any purchase sharing depends on the applicable Apple entitlement and eligibility; sharing access never shares evidence. Evidence stays separately on each device."]},{"title":"Managing storage","paragraphs":["In Settings, choose how long to keep recordings (30 days, 90 days or no time limit) and the recording storage limit (200 MB, 500 MB, 1 GB or 2 GB). The default is 30 days and 200 MB. The oldest records and their saved images are replaced when storage is full. Use Load more in the evidence library to view older entries. Delete All removes both pictures and score-only history after confirmation and device authentication."]},{"title":"Reporting an issue","paragraphs":["Provide the app version, device model, iOS version, access status and the action that failed. Contact support@ideaspike.com. Do not send passwords or private screenshots."]}]},"privacy":{"title":"Owl Guard AI Privacy Policy","sections":[{"title":"Screenshots stay on this device","paragraphs":["Owl Guard AI analyzes sampled screen images and text locally during a visible, user-authorized system broadcast. Selected screenshots and screening results are kept in the local evidence library on that device; the app does not send them to IDEASpike or a cloud AI provider. No Owl Guard AI registration is required."]},{"title":"Local storage and controls","paragraphs":["Recording history and saved images stay in protected storage and are excluded from backups. In Settings, choose a retention period (30 days by default, 90 days or no time limit) and a recording storage limit (200 MB by default, 500 MB, 1 GB or 2 GB). Expired records are removed on later access or a sample write. When the selected storage limit is reached, the oldest records and associated images are replaced. Reducing retention or storage asks for confirmation and device authentication. Delete All removes saved images and score-only history together."]},{"title":"Device authentication","paragraphs":["Face ID, Touch ID or the device passcode protects evidence viewing and deletion. The app receives an authentication result, not biometric templates."]},{"title":"Optional local alerts","paragraphs":["Alerts are optional and off by default for new users. Notifications use generic text without evidence images or extracted text. Delivery may be missed or delayed. Evidence review works with alerts disabled."]},{"title":"Apple purchases","paragraphs":["Apple handles payments, subscriptions and purchase restoration. Owl Guard AI verifies transactions and renewal status on the device and stores local access status, trial timing and subscription expiry. Screen content is not sent with a purchase.","Where Apple offers an eligible seven-day introductory free trial, the annual subscription then automatically renews at the localized annual price unless cancelled. Manage or cancel through Apple’s subscription settings. Existing verified one-time full-access purchases and non-renewing trial deadlines remain recognized without automatic subscription enrollment. Sharing eligible access never shares evidence."]},{"title":"Data collection","paragraphs":["The current app has no advertising, tracking or third-party analytics SDK, and no developer-run screen-data upload service. Its screen-analysis models and text rules are included in the app and run on the device rather than sending screenshots to a cloud AI provider. App downloads and updates, purchases, and optional website or support interactions still use network services. Apple may process data for its own App Store and operating-system services under Apple policies."]},{"title":"Your private media","paragraphs":["The evidence library stores selected screenshots, capture times and screening results for the categories you enable. Screenshots can contain personal information from other apps. You control recording, monitored categories, retention and deletion. Expanding selected categories or storage scope asks for renewed confirmation in Settings."]},{"title":"Contact","paragraphs":["Contact support@ideaspike.com for support or privacy questions. Do not send private screenshots. IDEASpike cannot remotely inspect or delete the evidence kept only on your device; use the local controls. Applicable privacy rights remain available."]},{"title":"This website and support email","paragraphs":["These public pages are hosted on GitHub Pages. The hosting provider processes normal web requests, which can include an IP address and browser information. These pages do not use advertising or analytics tools. If you email support, we use the message and your email address to respond through our email provider. Do not include private screenshots, passwords or payment details. This optional website or email interaction is separate from the app’s local screenshot processing."]}]},"terms":{"title":"Owl Guard AI Terms of Use","sections":[{"title":"Authorized monitoring","paragraphs":["Use Owl Guard AI only on a device you are entitled to use, with lawful authority and any permission required by applicable law. Start recording through Apple’s visible broadcast confirmation. Use the app lawfully and respect other people’s privacy rights. Review the selected screening categories and storage choices before recording."]},{"title":"Analysis and alert limits","paragraphs":["The app samples selected screen content and runs local models and text rules. Results can be incomplete, wrong or delayed. Optional alerts do not block or close other apps and may be affected by iOS notification settings. Owl Guard AI provides screening assistance; review retained evidence in context and use appropriate supervision."]},{"title":"Local evidence","paragraphs":["Captured images can contain sensitive messages and information from other apps. Device authentication protects evidence viewing and deletion. You control capture, categories, retention and storage. Expiry, capacity replacement and deletion can permanently remove recordings. Access sharing does not share evidence between devices."]},{"title":"Subscriptions and legacy access","paragraphs":["Where offered, an annual auto-renewing subscription may include an eligible seven-day introductory trial. Apple shows the local price, bills your Apple Account and manages eligibility and cancellation. Cancel at least 24 hours before the trial or current period ends to avoid renewal; manage the subscription in Apple’s settings. Restoration does not restart a trial. Existing verified one-time full access and non-renewing trial deadlines remain valid without automatic subscription enrollment. After access expires, new monitoring stops; retained recordings follow their retention rules."]},{"title":"Licence and intellectual property","paragraphs":["For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern the app\'s features, content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design, models and supplied content."]},{"title":"Purchases and consumer rights","paragraphs":["Purchases, restoration and refund requests follow Apple’s processes and applicable law. These product-specific conditions do not remove mandatory consumer rights."]},{"title":"Availability and your rights","paragraphs":["IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from screening results, missed or delayed alerts, or service interruption. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance."]}],"references":[{"label":"Apple Standard End User License Agreement","href":"https://www.apple.com/legal/internet-services/itunes/dev/stdeula/"}]},"updated":"Last updated: October 14, 2026"}'),p=JSON.parse('{"en":{"labels":{"updated":"Last updated: October 14, 2026","operator":"Operated by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>Your family data</h2><p>Learner Coin stores your parent email account, family name, member nicknames, tasks, notes, virtual balances, reward and activity history in its online service. Bank and investment features also store savings activity, simulated orders and positions, and related transaction records. AWS provides account authentication and storage. Use nicknames and include only information needed for family activities.</p>\\n<h2>Parent and child controls</h2><p>The parent account owns the family. Parent password protection is optional and can be enabled in Family. When enabled, parent controls lock after the configured access period, on switching to a child or when the app enters the background. Account deletion requires password verification. Parents should supervise family use and provide any permissions required by applicable law.</p>\\n<h2>Optional voice and AI processing</h2><p>Optional voice and AI features send your recording or typed instruction and the relevant family, draft or simulated-transaction information needed for your request to OpenAI. Review and confirm changes before saving. Manual entry remains available. Provider processing may take place outside your country, including the United States.</p>\\n<h2>Provider use and recordings</h2><p>OpenAI processes AI requests under its API data controls, which describe provider use and retention. By default, API data is not used to train models; model-improvement sharing requires an explicit opt-in by the API customer. Include only information needed for the instruction. Device recordings are removed after successful transcription, cancellation or leaving the recording flow; Learner Coin does not keep the audio as a saved family record.</p>\\n<h2>Voice diagnostics and saved actions</h2><p>Diagnostic instructions and related draft or action information used to troubleshoot the service are scheduled for cleanup after seven days. Audio recordings are not kept in those diagnostic records. Saved tasks, rewards, Bank and investment activity remain for your use until removed through the available controls or account deletion.</p>\\n<h2>Deleting your account and other requests</h2><p>In parent mode, open Family and choose Delete Account. The deletion flow removes the login account and associated active family, finance and voice records. If the app reports that deletion is incomplete, retry or contact support@ideaspike.com. Deleting the app or signing out does not delete the online account. Contact the same address for access, correction or a privacy complaint; we may verify that you control the account.</p>\\n<h2>Website and Apple services</h2><p>Opening a website or reference link sends ordinary web-request information, such as an IP address and browser information, to its hosting provider. Apple operates the App Store and device services under its own policies. Information you send to support is used to respond to your request. Do not send passwords, payment details or unnecessary personal information.</p>\\n<h2>Support and policy updates</h2><p>Contact support@ideaspike.com for support or privacy questions. Include only information needed to investigate the issue, without passwords, verification codes or unnecessary information about children. We will update this policy when relevant data practices change.</p>\\n<p><a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API data controls</a></p>"},"terms":{"title":"Terms of Use","body":"<h2>Family tasks and rewards</h2><p>Learner Coin helps families organize tasks, approvals, rewards and learning activities. Parents are responsible for setting appropriate tasks and fulfilling any real-world reward promises they make. The service does not guarantee a child’s learning, behaviour or financial outcome.</p>\\n<h2>Virtual finance and investment learning</h2><p>Learner Coin includes Bank and savings ledgers and simulated investment orders and positions. Coins, Bank balances, deposits, withdrawals, interest, borrowing, fees and trades shown in these features are family learning records or simulations. They do not open a real bank or brokerage account, transfer or safeguard real money, purchase securities, provide deposit insurance or create a right to redeem value from IDEASpike. Any actual exchange or reward arranged within a family occurs outside these app ledgers.</p>\\n<h2>Reference information and decisions</h2><p>Reference prices, rates and other market information may be delayed, unavailable, incomplete or wrong. Simulated execution, returns and borrowing terms can differ materially from real markets. The app does not provide personalized investment, financial, tax or legal advice. Review amounts, instruments and the displayed preview before confirming an operation. Keep independent records of any real-world family arrangements.</p>\\n<h2>Accounts, children and AI</h2><p>Use only accounts and family profiles you are authorized to access. Parents should supervise children’s use, protect account access and provide the permissions required by applicable law. Submit voice or text to the AI feature only when you have the required permission for that information. AI may misunderstand instructions or produce incorrect drafts. Voice instructions prepare or navigate visible forms; review and confirm the relevant save or simulated transaction yourself.</p>\\n<h2>Licence and intellectual property</h2><p>For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content. You retain rights in content you provide and permit IDEASpike and its processors to process it for the features and optional data uses you choose, as described in the Privacy Policy.</p>\\n<h2>Responsible use</h2><p>Use the app lawfully. Do not submit unlawful or infringing content, attempt to access another family’s records or disrupt the service.</p>\\n<h2>Availability and your rights</h2><p>IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app and online service are provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from family arrangements, simulated financial results, AI drafts or service interruption. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"},"support":{"title":"Support","body":"<h2>Family, tasks and rewards</h2><p>Sign in to the parent account, create your family and use child nicknames. Add tasks and rewards, review submissions and confirm actions in the appropriate parent or child profile. Enable parent password protection in Family when you need the additional access control.</p>\\n<h2>Bank and investment ledgers</h2><p>Bank, savings, activity, orders and positions are learning features. They record virtual amounts and simulated investments rather than moving real money. Use the displayed preview and confirm the amount, instrument and selected child before saving. If a reference price is unavailable or an operation is pending, use the status or retry controls and check activity before submitting another operation.</p>\\n<h2>Voice drafts and saves</h2><p>You can type manually or use the optional OpenAI voice flow. Review the AI-sharing notice before using it. Recording or typing an instruction may transmit the information, visible drafts and simulated investment context described in the Privacy Policy. AI does not replace your review: use the visible confirmation to save tasks, rewards or simulated financial actions. If interpretation fails, edit the instruction or use manual controls.</p>\\n<h2>Account deletion and privacy</h2><p>In parent mode, open Family and choose Delete Account, then complete password verification. If the app reports that deletion is incomplete, retry or contact support@ideaspike.com. Removing the app or signing out alone does not remove cloud family records.</p>\\n<h2>Contact support</h2><p>Email support@ideaspike.com with the app version, device, operating-system version and a short description. Describe the type of failed operation without sending passwords, verification codes, payment details, private recordings or unnecessary information about children.</p>"}}}'),c=JSON.parse('{"en":{"labels":{"updated":"Last updated: October 10, 2026","operator":"Operated by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>A two-device voice pilot</h2><p>Translate Talkie pairs two devices in a configured room for short translated voice messages. No separate personal account is required. A randomly generated device identifier and chosen language are saved on the device and sent to the room service. That identifier is not proof of the speaker’s identity.</p>\\n<h2>Audio, text and recipients</h2><p>Microphone permission lets the app record while you hold the talk control. The recording is uploaded to the AWS-hosted service. OpenAI processes audio for transcription, text for translation and translated text for synthesized speech. The other paired device receives message text and translated audio. Request/room identifiers, timestamps and processing errors support delivery and troubleshooting. Do not record bystanders or share another person’s speech without the necessary permission.</p>\\n<h2>Retention and local storage</h2><p>The service’s room-message events, including translated text and audio, are configured to expire after about five minutes. Database expiration is asynchronous and may take longer. The current app keeps the visible conversation in memory during the running session; its device identifier and language preference persist locally. Temporary recording files are normally removed after the app reads the recording; interrupted or very short recordings may remain until later cleanup. Provider processing and operational logs are separate from room expiry, and copies held by a recipient are outside our control.</p>\\n<h2>Providers and your choices</h2><p>AWS hosts room state and message delivery. OpenAI’s separate processing, retention and data-use settings apply to the transcription, translation and speech services. Processing may occur outside your country, including the United States. You can deny microphone permission or stop recording and leave the app. This pilot does not authenticate the other speaker or provide private enterprise rooms; confirm who is paired and avoid confidential information. Contact support for room/device-data assistance.</p>\\n<h2>Website, Apple services and support</h2><p>Opening a website or reference link sends ordinary web-request information, such as an IP address and browser information, to its hosting provider. Apple operates the App Store, TestFlight and device services under its own policies; feedback you choose to send through TestFlight may be visible to the developer. If you email support, we use your email address and message to respond. Do not send passwords, payment details or unnecessary personal information.</p>\\n<h2>Changes and privacy assistance</h2><p>This policy applies to this application. We update it when its processing changes. Contact support@ideaspike.com for privacy questions, access, correction or deletion assistance. Applicable privacy rights remain available. Retained support correspondence may be needed to handle your request or meet legal obligations.</p>\\n<h2>AI provider policy</h2><p>See <a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API data controls</a> for provider processing, retention and data-sharing settings. Room expiry or deletion from our service does not control a provider’s separate records.</p>"},"terms":{"title":"Terms of Use","body":"<h2>Controlled conversations</h2><p>Use this pre-release tool for short, supervised conversations between the two intended participants. Make sure each speaker understands that audio is uploaded for AI processing and that the other device receives the result. Do not record others without the permissions required in your circumstances.</p>\\n<h2>Translation limits</h2><p>This is recorded voice messaging, not continuous simultaneous interpretation. Transcription, translation and synthesized speech may omit words, change meaning or identify the wrong language. Check important meanings with the other participant. Do not rely on it for medical, legal, emergency, financial or confidential decisions.</p>\\n<h2>Room access and conduct</h2><p>The current demo room does not verify participant identity. Automatic pairing is not a security guarantee. Do not impersonate speakers, submit unlawful or abusive recordings, or interfere with another conversation. A venue’s operator is responsible for appropriately explaining and supervising its pilot use.</p>\\n<h2>Testing and continuity</h2><p>Network or provider failures can prevent delivery. Conversations are not a durable history service, and messages or room state may expire or reset. This pilot does not offer payments or subscriptions. Keep any needed record independently and with appropriate permission.</p>\\n<h2>Availability and your rights</h2><p>Features may change and depend on compatible devices, connectivity and third-party services where used. Pre-release testing may be interrupted or reset; keep any information you need independently. Nothing in these terms excludes rights or responsibilities that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"},"support":{"title":"Translate Talkie Support","body":"<h2>Pair and talk</h2><p>Open the configured pilot app on two phones and wait for the paired status. Choose each phone’s language, hold the talk control to record, then release to send. Tap an incoming bubble to play its translated voice.</p>\\n<h2>Troubleshoot a pilot</h2><p>Check microphone permission, network access and the paired-room status. The current demo room supports two devices; an unintended active device can prevent the expected pairing. Check the selected language and keep recordings short. The conversation is not preserved as a permanent history.</p>\\n<h2>Contact support</h2><p>Email support@ideaspike.com with the app version, device model, operating-system version and a short description of the issue. During private testing you can also use TestFlight feedback. Do not send passwords, sign-in codes, payment details or private recordings.</p>"}}}'),d={mirror:r,"prices-nearby":i,"learner-coin":p,"translate-talkie":c,understone:JSON.parse('{"en":{"labels":{"updated":"Last updated: October 14, 2026","operator":"Understone by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>The app and your data</h2><p>Understone is a mineral-deduction game. It does not require an app account. We do not collect or send your gameplay, progress, local scores or sound settings to IDEASpike servers, and we do not use advertising, tracking or third-party analytics in the app.</p>\\n<h2>Information on your device</h2><p>The app saves your current expedition, discovered specimens, completed local scores and sound settings in its local storage. New Game replaces the current expedition but retains completed scores and sound settings. Deleting the app removes its local app data; copies may remain in device backups managed by Apple. The app does not operate cross-device synchronization. IDEASpike cannot remotely recover or delete these local files or your device backups; backup availability and restoration depend on your Apple/device settings.</p>\\n<h2>Apple purchases</h2><p>Apple processes the one-time full-expedition purchase. The app receives product, storefront and verified transaction information from Apple to display the local price, check your unlock and restore it. We do not receive your payment-card details or Apple Account password, and the app does not send transaction information to an IDEASpike server. Apple’s own privacy terms govern its purchase processing.</p>\\n<h2>Optional external links</h2><p>Geological research, music credits, support and privacy links open external pages only when you choose them. Those websites and your browser may process information under their own privacy policies. The app does not automatically upload your expedition when opening a link.</p>\\n<h2>Your choices and questions</h2><p>You can play the opening district without making a purchase, adjust sound settings, replace the current expedition or remove the app. Purchases and refunds are managed through Apple. Email support@ideaspike.com for privacy questions; any information you choose to send in a support email is used to respond to your request. Do not include passwords or payment-card details. Applicable privacy rights remain available.</p>\\n<h2>Policy updates</h2><p>This policy describes the current release. We will update it if the app’s data practices change.</p>"},"support":{"title":"App Support","body":"<h2>Plan each dig</h2><p>Tap an unexplored cell to reveal it. Opening a gem spends its mining cost immediately. Tap the mined gem again to collect it for free and earn XP. Empty cells and clue numbers are free; a clue adds the mining costs in its eight neighboring cells. Red warning marks count neighboring lethal mines.</p>\\n<h2>Recover stamina and keep exploring</h2><p>Stamina may reach zero. Eat a revealed hamburger when you need a full refill, or upgrade manually after earning enough XP. Restarting a failed floor creates a fresh map and restores that floor’s entry state. The interactive practice tutorial is available when starting a new game and from the in-game help page.</p>\\n<h2>Free opening and full expedition</h2><p>The opening district has three free floors and a camp shop. Leaving that first camp opens the one-time Unlock all field sites purchase. The full campaign spans eight districts and 24 floors; the one-time unlock opens the remaining field sites, with no subscription. Apple displays the price in your App Store currency. Camp items use earned game coins, not real money.</p>\\n<h2>Purchase and restore help</h2><p>Purchases are processed by Apple. Use Restore purchases on the unlock page with the eligible Apple Account. Restoration verifies full-game access; it does not restore a deleted expedition. A pending purchase unlocks only after a valid Apple transaction is verified; canceling preserves your progress. Review a changed price or currency before confirming a new offer. If prices or purchases are unavailable, check your connection, retry, and contact us if the issue continues. Do not buy again to resolve an existing purchase. Apple refund requests are handled at reportaproblem.apple.com, subject to eligibility and applicable law.</p>\\n<h2>Progress and sound</h2><p>Load Progress resumes the expedition saved on this device. New Game replaces the current expedition; completed local scores and sound settings remain. Settings lets you adjust music and effects or return to the main menu. This release has local scores and no online account or developer-operated cloud sync. Device backups are controlled by Apple and your settings.</p>\\n<h2>Contact support</h2><p>Email support@ideaspike.com with the app version, device, iOS version and a short description of the problem. Do not send passwords, full payment details or unnecessary personal information.</p>"},"terms":{"title":"Terms of Use","body":"<h2>Game and educational content</h2><p>Understone combines public clues, resource planning and gemstone collection. Mineral descriptions and references support learning; game costs, rarity, values and map distributions are game rules and are not real-world mineral prices, mining instructions or safety advice. Educational descriptions can contain inaccuracies or simplifications; verify important real-world information independently.</p>\\n<h2>Trial and full access</h2><p>The opening district’s three floors and first camp are free to play. Continuing beyond that camp requires the one-time non-consumable full-game unlock through Apple. The full expedition spans eight districts and 24 floors; this is not a subscription. Apple displays the applicable offer and price and handles payment. Restore Purchases checks the eligible Apple Account’s valid entitlement; a pending, refunded or revoked transaction does not itself guarantee access. A price or currency change may require review of the new offer. Refund requests follow Apple’s process and applicable law; mandatory consumer rights remain available.</p>\\n<h2>Local progress and retries</h2><p>Failure can roll back the current floor attempt to its entry state and generate a new map. Replacement expeditions and deleted saves may not be recoverable. Keep device access secure and consider your backup settings. Restoring an entitlement does not recreate local progress.</p>\\n<h2>Licence and intellectual property</h2><p>For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern the app\'s features, content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the game for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design, artwork, music and supplied content, subject to identified third-party licences.</p>\\n<h2>Responsible use</h2><p>Use the game lawfully, respect its content licenses and do not interfere with its operation or purchase verification. Learning and play outcomes are not guaranteed. Features depend on supported devices and Apple services.</p>\\n<h2>Availability and your rights</h2><p>IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the game is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from local-progress loss, interruption or reliance on educational content. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"}},"zh-Hans":{"labels":{"updated":"更新日期：2026年10月14日","operator":"Understone 由 IDEASpike 提供。联系："},"privacy":{"title":"隐私政策","body":"<h2>应用与数据</h2><p>Understone 是矿物推理游戏，无需应用账户。我们不会将游戏过程、进度、本地成绩或声音设置收集或发送到 IDEASpike 服务器。应用不含广告、跟踪或第三方分析服务。</p>\\n<h2>设备上的信息</h2><p>当前探险、已发现标本、已完成的本地成绩和声音设置保存在应用的本地存储中。“新游戏”替换当前探险，并保留完成成绩和声音设置。删除应用会删除其本地应用数据；Apple 管理的设备备份中可能仍有副本。应用不提供跨设备同步。IDEASpike 无法远程恢复或删除这些本地文件及设备备份；备份是否可用及能否恢复取决于你的 Apple 或设备设置。</p>\\n<h2>Apple 购买</h2><p>一次性完整探险购买由 Apple 处理。应用从 Apple 接收商品、商店地区和已验证交易信息，用于显示当地价格、检查解锁状态和恢复购买。我们不会获得付款卡资料或 Apple 账户密码，应用也不会将交易信息发送至 IDEASpike 服务器。Apple 的购买处理适用其自身隐私条款。</p>\\n<h2>可选外部链接</h2><p>仅在你主动选择时，地质研究、音乐鸣谢、支持和隐私链接才会打开外部网页。这些网站和浏览器可能按各自的隐私政策处理信息。打开链接不会自动上传你的探险数据。</p>\\n<h2>选择与问题</h2><p>你可以不购买而体验第一个矿区，也可调整声音、替换当前探险或移除应用。购买和退款由 Apple 管理。隐私问题可发送至 support@ideaspike.com；你主动提供的支持邮件信息仅用于回复请求。请勿包含密码或付款卡资料。适用的隐私权利仍然有效。</p>\\n<h2>政策更新</h2><p>本政策描述当前版本。若应用的数据处理方式变化，我们会更新此政策。</p>"},"support":{"title":"应用支持","body":"<h2>规划每次采集</h2><p>点击未探索的格子进行探索。打开宝石格时立即扣除采集所需精力，再点一次可免费收集宝石并获得经验。空格和提示数字不消耗精力；数字表示周围八个格子的采集消耗总和。红色警示标记的数量表示周围地雷的数量。</p>\\n<h2>恢复精力，继续探险</h2><p>精力可以降到零。在需要恢复时吃已发现的汉堡，可以补满精力；经验足够时也可手动升级。失败后重试会生成新地图，并恢复当前小关进入时的状态。新游戏和游戏内帮助页面都提供交互式练习导览。</p>\\n<h2>免费开局与完整探险</h2><p>第一个矿区包含三个免费小关和营地商店。离开第一个营地时，可通过一次性购买“解锁全部矿区”继续后续探险。完整探险包含八个矿区、24个小关，无需订阅。Apple 按你的 App Store 地区显示当地货币价格。营地商品使用游戏中获得的金币购买。</p>\\n<h2>购买与恢复</h2><p>购买由 Apple 处理。在解锁页面使用“恢复购买”，并登录符合条件的 Apple 账户。恢复购买验证完整游戏权益，不会恢复已删除的探险。等待批准的购买仅在有效 Apple 交易通过验证后解锁；取消购买会保留进度。金额或币种改变时，请先查看新报价再确认。价格或购买不可用时，请检查网络后重试，仍有问题可联系我们。请勿重复购买来解决已有交易问题。退款可在 reportaproblem.apple.com 申请，是否符合条件取决于 Apple 政策和适用法律。</p>\\n<h2>进度与声音</h2><p>“读取进度”继续本设备上的存档。“新游戏”替换当前探险，但保留已完成的本地成绩和声音设置。设置可调整音乐、音效或返回主界面。本版本使用本地成绩，无应用账户或开发者提供的云同步。设备备份由 Apple 和你的系统设置管理。</p>\\n<h2>联系支持</h2><p>请发送邮件至 support@ideaspike.com，说明应用版本、设备、iOS 版本和问题。请勿发送密码、完整付款资料或不必要的个人信息。</p>"}},"zh-Hant":{"labels":{"updated":"更新日期：2026年10月14日","operator":"Understone 由 IDEASpike 提供。聯絡："},"privacy":{"title":"隱私政策","body":"<h2>應用與資料</h2><p>Understone 是礦物推理遊戲，無需應用帳號。我們不會將遊戲過程、進度、本機成績或聲音設定收集或傳送到 IDEASpike 伺服器。應用不含廣告、追蹤或第三方分析服務。</p>\\n<h2>裝置上的資訊</h2><p>目前探險、已發現標本、已完成的本機成績和聲音設定保存在應用的本機儲存中。「新遊戲」替換目前探險，並保留完成成績和聲音設定。刪除應用會刪除其本機應用資料；Apple 管理的裝置備份中可能仍有副本。應用不提供跨裝置同步。IDEASpike 無法遠端復原或刪除這些本機檔案及裝置備份；備份是否可用及能否復原取決於你的 Apple 或裝置設定。</p>\\n<h2>Apple 購買</h2><p>一次性完整探險購買由 Apple 處理。應用從 Apple 接收商品、商店地區和已驗證交易資訊，用於顯示當地價格、檢查解鎖狀態和恢復購買。我們不會取得付款卡資料或 Apple 帳號密碼，應用也不會將交易資訊傳送至 IDEASpike 伺服器。Apple 的購買處理適用其自身隱私條款。</p>\\n<h2>可選外部連結</h2><p>僅在你主動選擇時，地質研究、音樂鳴謝、支援和隱私連結才會打開外部網頁。這些網站和瀏覽器可能按各自的隱私政策處理資訊。打開連結不會自動上傳你的探險資料。</p>\\n<h2>選擇與問題</h2><p>你可以不購買而體驗第一個礦區，也可調整聲音、替換目前探險或移除應用。購買和退款由 Apple 管理。隱私問題可傳送至 support@ideaspike.com；你主動提供的支援郵件資訊僅用於回覆請求。請勿包含密碼或付款卡資料。適用的隱私權利仍然有效。</p>\\n<h2>政策更新</h2><p>本政策描述目前版本。若應用的資料處理方式變化，我們會更新此政策。</p>"},"support":{"title":"應用程式支援","body":"<h2>規劃每次採集</h2><p>點擊未探索的格子進行探索。打開寶石格時立即扣除採集所需精力，再點一次可免費收集寶石並獲得經驗。空格和提示數字不消耗精力；數字表示周圍八個格子的採集消耗總和。紅色警示標記的數量表示周圍地雷的數量。</p>\\n<h2>恢復精力，繼續探險</h2><p>精力可以降到零。在需要恢復時吃已發現的漢堡，可以補滿精力；經驗足夠時也可手動升級。失敗後重試會產生新地圖，並恢復目前小關進入時的狀態。新遊戲和遊戲內說明頁面都提供互動式練習導覽。</p>\\n<h2>免費開局與完整探險</h2><p>第一個礦區包含三個免費小關和營地商店。離開第一個營地時，可透過一次性購買「解鎖全部礦區」繼續後續探險。完整探險包含八個礦區、24個小關，無需訂閱。Apple 按你的 App Store 地區顯示當地貨幣價格。營地商品使用遊戲中獲得的金幣購買。</p>\\n<h2>購買與恢復</h2><p>購買由 Apple 處理。在解鎖頁面使用「恢復購買」，並登入符合條件的 Apple 帳號。恢復購買驗證完整遊戲權益，不會復原已刪除的探險。等待批准的購買僅在有效 Apple 交易通過驗證後解鎖；取消購買會保留進度。金額或幣別改變時，請先查看新報價再確認。價格或購買不可用時，請檢查網路後重試，仍有問題可聯絡我們。請勿重複購買來解決已有交易問題。退款可在 reportaproblem.apple.com 申請，是否符合條件取決於 Apple 政策和適用法律。</p>\\n<h2>進度與聲音</h2><p>「讀取進度」繼續本裝置上的存檔。「新遊戲」替換目前探險，但保留已完成的本機成績和聲音設定。設定可調整音樂、音效或返回主畫面。本版本使用本機成績，無應用帳號或開發者提供的雲端同步。裝置備份由 Apple 和你的系統設定管理。</p>\\n<h2>聯絡支援</h2><p>請傳送郵件至 support@ideaspike.com，說明應用版本、裝置、iOS 版本和問題。請勿傳送密碼、完整付款資料或不必要的個人資訊。</p>"}}}'),epocharium:JSON.parse('{"en":{"labels":{"updated":"Last updated: October 14, 2026","operator":"Operated by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>The service</h2><p>Epocharium is a museum-building game provided by IDEASpike. An online account keeps your museum progress available when you sign in. This policy explains how the service handles account and game information.</p>\\n<h2>Account and museum information</h2><p>AWS provides account authentication and storage. Account information includes your email and the information needed to sign in, verify your account and recover access. Museum records include your layout, collection, resources, progress and game actions. The app keeps protected session and pending-action information on your device. Do not send passwords or verification codes to support.</p>\\n<h2>Cloud processing and diagnostics</h2><p>AWS stores account and museum records. Processing may take place outside your country, including the United States. Service logs are kept for approximately seven days to operate and troubleshoot the service. Museum play does not require photos, audio recordings or location information.</p>\\n<h2>Retention and account deletion</h2><p>Account and museum records remain while you use the service. Use Delete Account in account settings to delete your login and associated museum information. Account deletion is permanent. Signing out or removing the app does not delete the online account. Contact support@ideaspike.com for access, correction or privacy questions; we may verify that you control the account.</p>\\n<h2>Apple and purchases</h2><p>Apple processes App Store purchases under its own policies. If you make a purchase, the service processes the transaction information needed to deliver the stated game entitlement and provide purchase assistance. We do not receive payment-card details.</p>\\n<h2>Website and Apple services</h2><p>Opening a website or reference link sends ordinary web-request information, such as an IP address and browser information, to its hosting provider. Information you send to support is used to respond to your request. Do not send passwords, payment details or unnecessary personal information.</p>\\n<h2>Support and policy updates</h2><p>Information you choose to email to support@ideaspike.com is used to address your request. Include only what is needed and omit sensitive account details. You may raise a privacy question or complaint without giving up rights under applicable law. We will update this policy when the relevant data practices change.</p>"},"terms":{"title":"Terms of Use","body":"<h2>The service</h2><p>Epocharium lets you build and manage a museum, arrange exhibits and collections, and develop in-game resources and progress.</p>\\n<h2>Accounts and responsible use</h2><p>Use an account you are authorized to access, protect your sign-in details and use the app lawfully. Do not interfere with other accounts, exploit purchase verification, disrupt the service or use content without the required rights. A parent or guardian must provide any permission required by applicable law for a child’s use.</p>\\n<h2>Museum and educational content</h2><p>Exhibits, descriptions and game values are for play and general learning. They may contain inaccuracies or simplified interpretations. In-game ownership does not transfer ownership of a real exhibit, intellectual-property rights or a real-world asset. Respect the applicable licenses and attribution for supplied content.</p>\\n<h2>Licence and intellectual property</h2><p>For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content.</p>\\n<h2>In-game resources and purchases</h2><p>In-game resources, exhibits and entitlements are for use in Epocharium. They are not bank deposits, investments or real-world ownership, and are not redeemable for cash except where required by law. One-time in-app purchases provide the game items or resources described in the app. Review the stated item, price and currency before confirming an Apple purchase. Apple handles payment and App Store refund requests under its policies and applicable law. Contact support for an undelivered purchase before purchasing again. Nothing here waives mandatory consumer rights.</p>\\n<h2>Availability and your rights</h2><p>IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from loss of game progress, interruption or reliance on game content. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"},"support":{"title":"Support","body":"<h2>Sign in</h2><p>Create or sign in to your Epocharium account using your email address. Complete the email-verification step when requested. Use the confirmation-code resend or password-recovery flow if needed. Check your internet connection and the address you entered. Never email your password, recovery code or sign-in token.</p>\\n<h2>Museum progress and interrupted actions</h2><p>The cloud service maintains the museum associated with your signed-in account. If loading or an action fails, reconnect and use the app’s retry or recovery controls before repeating the action. Signing out, reinstalling or using a different account does not constitute cloud-account deletion.</p>\\n<h2>Purchases</h2><p>For an App Store purchase, check your Apple purchase history and sign in to the game account used for the purchase. If the stated item has not arrived, contact support before attempting another purchase. Apple handles App Store refund requests under its policies and applicable law.</p>\\n<h2>Account deletion and support</h2><p>Use Delete Account in account settings to delete your account and associated online museum information. For support, access, correction or privacy questions, email support@ideaspike.com with the app version, device model, iOS version and a short description. Do not include passwords, sign-in codes, payment-card details or unnecessary personal information.</p>"}}}')},l={privacy:"Privacy Policy",terms:"Terms of Use",support:"Support"},u={privacy:"privacy",terms:"tos",support:"support"};function h(e,a){var t;if("final-curtain"===e)return"support"===a?["en"]:["en","zh-Hans","zh-Hant"];if("owlguard-ai"===e)return["en"];let r=null!=(t=d[e])?t:{};return Object.keys(r).filter(e=>{var t;return null==(t=r[e])?void 0:t[a]})}function m(e,a){var t;let r=arguments.length>2&&void 0!==arguments[2]?arguments[2]:"en";if("final-curtain"===e){if("support"===a)return o;let e=n[r];return{title:"privacy"===a?e.privacyTitle:e.termsTitle,updated:e.updated,sections:e[a].map(e=>{let[a,t]=e;return{title:a,paragraphs:[t]}})}}if("owlguard-ai"===e)return{...s[a],updated:s.updated};let i=d[e];if(!i)throw Error("Unknown application: ".concat(e));let p=(null==(t=i[r])?void 0:t[a])?i[r]:i.en,c=p[a];if(!c)throw Error("Missing ".concat(a," document for ").concat(e));return{...c,updated:p.labels.updated}}},7995:e=>{e.exports=JSON.parse('{"en":{"updated":"Updated October 14, 2026","privacyTitle":"Privacy Policy","termsTitle":"Terms of Service","contact":"Contact","privacy":[["What Final Curtain does","Final Curtain is a local time-reflection app. It estimates remaining time from a birth date and a horizon you choose, and lets you explore recurring activities, large time blocks, reserves and separate profiles. It does not predict lifespan."],["Information on your device","Birth dates, profile names, chosen horizons, activity names and amounts, retirement or graduation assumptions, and block/reserve settings are stored on the current device. The widget uses the selected horizon locally on your device. The app has no separate app account, custom backend or app-provided cloud synchronization."],["Optional on-device AI","On supported devices with Apple Intelligence enabled, a summary can use Apple’s on-device model. Allocation data is processed on the device and is not sent to IDEASpike or a cloud AI provider. Generated text can be incomplete or inaccurate and is not a diagnosis or prediction."],["Apple purchases and services","Apple processes the optional Final Curtain Pro purchase. Apple provides product and purchase-entitlement information so the app can unlock Pro and recognize an eligible legacy widget purchase; we do not receive payment-card details. Apple’s App Store and device services operate under Apple’s own policies."],["Storage and your choices","You can remove activities, clear a list, edit assumptions and delete additional profiles in the app. At least one profile remains. Removing the app removes its app-local files; device backups may retain copies according to your Apple/device backup settings. We do not provide cross-device recovery or remote deletion of your backups."],["Website and contact","Opening legal or reference links contacts the destination website. Hosting providers receive ordinary web-request information such as IP addresses. Information you choose to email to support is used to respond to your request. The app does not include advertising or developer-added tracking/analytics SDKs."],["Changes and assistance","We update this page when processing changes. For questions or assistance, contact support@ideaspike.com. This policy applies to Final Curtain; other IDEASpike apps have their own policies."]],"terms":[["Purpose and estimates","Final Curtain helps you reflect on finite time and compare choices. Birth date, life horizon, rates, block durations and end dates are assumptions you control. Estimates are not predictions, commitments or guarantees that you will complete any activity."],["Your choices","You decide what matters, whether to change an allocation, and whether to follow any suggestion. Example amounts and population averages are not personal targets. Large blocks replace routine time from today; needs inside those periods are included. References explain comparisons, not an optimal life plan."],["AI and health","Optional on-device summaries can be incomplete or inaccurate. The app does not provide medical, financial or other professional advice, diagnose a person, or determine their worth. For sleep or health concerns, consult an appropriate professional rather than relying on allocation arithmetic."],["Purchases","Final Curtain Pro unlocks Compare Choices and the Home Screen widget through a one-time non-consumable Apple purchase, rather than a subscription. An eligible verified legacy widget purchase also grants Pro access. Apple displays the current offer and price and handles payment. Restoration depends on the applicable Apple Account and a valid StoreKit entitlement; refunded or revoked entitlements may no longer unlock Pro. Restoring a purchase does not restore deleted local planning data. Refund requests follow Apple’s process and applicable law; these terms do not limit mandatory consumer rights."],["Local data","Keep device access secure and consider your backup settings. Profiles stay on the current device and are not app accounts. Single-activity deletion occurs immediately, including a full swipe; clearing the list and deleting a profile require confirmation. We do not guarantee recovery of removed local data."],["Licence and intellectual property","For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern the app\'s features, content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content."],["Use and availability","Use the app lawfully and respect other people’s privacy when entering their information. IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from reliance on estimates, generated reflections or service interruption. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law."],["Updates and contact","Updated terms appear on this page. Contact support@ideaspike.com for app questions or purchase assistance."]]},"zh-Hans":{"updated":"更新于 2026 年 10 月 14 日","privacyTitle":"隐私政策","termsTitle":"使用条款","contact":"联系","privacy":[["应用提供什么","Final Curtain 是本地时间反思应用。它依据生日和你选择的人生期限估算剩余时间，帮助你探索日常活动、大块时间、预留余量及不同档案。它不会预测寿命。"],["本设备上的信息","生日、档案名称、人生期限、活动名称和时间量、退休或毕业假设及大块时间与预留设置保存在当前设备。小组件在本设备上使用所选期限。应用没有独立登录账户、自建后台或应用提供的云同步。"],["可选的设备端 AI","在支持 Apple Intelligence 且已启用的设备上，总结可使用 Apple 设备端模型。活动分配数据只在设备上处理，不会发送给 IDEASpike 或云端 AI 服务商。生成内容可能不完整或不准确，不是诊断或预测。"],["Apple 购买与服务","Apple 处理可选的 Final Curtain Pro 购买。Apple 提供商品与购买权益信息，供应用解锁 Pro 并识别符合条件的旧版小组件购买；我们不接收银行卡资料。App Store 和设备服务适用 Apple 自己的政策。"],["保存期限与选择","你可删除活动、清空清单、修改假设及删除多余档案。至少保留一个档案。删除应用会删除其本地文件；Apple 或设备备份可能依照你的备份设置保留副本。我们不提供跨设备恢复，也不能远程删除你的备份。"],["网站与联系","打开法律或参考链接会连接到目标网站，托管服务会收到 IP 地址等常规请求信息。你主动发送给支持邮箱的信息用于回复请求。应用不包含广告或开发者添加的跟踪、分析 SDK。"],["更新与协助","处理方式改变时会更新本页。有问题可联系 support@ideaspike.com。本政策适用于 Final Curtain，其他 IDEASpike 应用有各自政策。"]],"terms":[["用途与估算","Final Curtain 帮助你认识有限时间并比较选择。生日、人生期限、时间量、大块活动时长和结束期限均是你控制的假设。结果不是预测、承诺或完成活动的保证。"],["你的选择","什么重要、是否调整时间及是否采纳建议，均由你决定。示例数值和群体平均值不是个人目标。大块时间从今天起替代日常时间，期间的生活需要已包含在内。参考资料用于解释比较，并不代表最优人生方案。"],["AI 与健康","可选的设备端总结可能不完整或不准确。应用不提供医疗、财务等专业建议，不诊断个人，也不衡量个人价值。睡眠或健康问题应咨询相应专业人士，而非依赖时间分配计算。"],["购买","Final Curtain Pro 通过 Apple 的一次性非消耗型购买解锁“比较选择”和主屏幕小组件，无需订阅。符合条件且已验证的旧版小组件购买也可获得 Pro 权益。Apple 显示当前商品与价格并处理付款。恢复购买依赖相应 Apple 账户及有效的 StoreKit 权益；已退款或撤销的权益可能不再解锁 Pro。恢复购买不会恢复已删除的本地规划数据。退款遵循 Apple 流程和适用法律；这些条款不限制强制性消费者权利。"],["本地数据","请保护设备访问安全并了解备份设置。档案只保存在当前设备，不是应用账户。单项活动会立即删除，包括完整左滑；清空清单和删除档案仍需确认。我们不保证恢复已删除的本地数据。"],["许可与知识产权","通过 App Store 下载的应用，除非 App Store Connect 已为你所在国家或地区指定自定义最终用户许可协议，否则其应用许可受 Apple 标准最终用户许可协议约束。本条款补充适用的许可协议，并规范本应用的功能、内容和付费权益（如有）。在该协议和本条款约束下，IDEASpike 授予你仅为预定用途使用本应用的有限、个人且不可转让许可。应用、软件、设计及所提供内容的全部权利由 IDEASpike 及其许可方保留。"],["使用与可用性","请合法使用应用，录入他人信息时尊重其隐私。IDEASpike 可更新、暂停或停止功能。在法律允许的范围内，应用按可用状态提供，除本条款明确约定或法律要求外，不作出额外保证；对于依赖估算、生成的反思文字或服务中断造成的间接或后果性损失，IDEASpike 不承担责任。本条款不排除依法不得排除的责任或消费者权利。"],["更新与联系","更新条款会在本页发布。应用问题或购买协助可联系 support@ideaspike.com。"]]},"zh-Hant":{"updated":"更新於 2026 年 10 月 14 日","privacyTitle":"隱私政策","termsTitle":"使用條款","contact":"聯絡","privacy":[["App 提供什麼","Final Curtain 是本機時間反思 App。它依據生日和你選擇的人生期限估算剩餘時間，協助你探索日常活動、大段時間、預留餘量及不同檔案。它不會預測壽命。"],["本裝置上的資訊","生日、檔案名稱、人生期限、活動名稱和時間量、退休或畢業假設及大段時間與預留設定保存在目前裝置。小工具在本裝置上使用所選期限。App 沒有獨立登入帳號、自建後台或 App 提供的雲端同步。"],["可選的裝置端 AI","在支援 Apple Intelligence 且已啟用的裝置上，總結可使用 Apple 裝置端模型。活動分配資料只在裝置上處理，不會傳送給 IDEASpike 或雲端 AI 服務商。產生內容可能不完整或不準確，不是診斷或預測。"],["Apple 購買與服務","Apple 處理可選的 Final Curtain Pro 購買。Apple 提供商品與購買權益資訊，供 App 解鎖 Pro 並識別符合條件的舊版小工具購買；我們不接收銀行卡資料。App Store 和裝置服務適用 Apple 自己的政策。"],["保存期限與選擇","你可刪除活動、清空清單、修改假設及刪除多餘檔案。至少保留一個檔案。刪除 App 會刪除其本機檔案；Apple 或裝置備份可能依照你的備份設定保留副本。我們不提供跨裝置復原，也不能遠端刪除你的備份。"],["網站與聯絡","開啟法律或參考連結會連接目標網站，託管服務會收到 IP 位址等一般請求資訊。你主動傳送給支援信箱的資訊用於回覆請求。App 不包含廣告或開發者新增的追蹤、分析 SDK。"],["更新與協助","處理方式改變時會更新本頁。有問題可聯絡 support@ideaspike.com。本政策適用於 Final Curtain，其他 IDEASpike App 有各自政策。"]],"terms":[["用途與估算","Final Curtain 協助你認識有限時間並比較選擇。生日、人生期限、時間量、大段活動時長和結束期限均是你控制的假設。結果不是預測、承諾或完成活動的保證。"],["你的選擇","什麼重要、是否調整時間及是否採納建議，均由你決定。範例數值和群體平均值不是個人目標。大段時間從今天起取代日常時間，期間的生活需要已包含在內。參考資料用於解釋比較，並不代表最優人生方案。"],["AI 與健康","可選的裝置端總結可能不完整或不準確。App 不提供醫療、財務等專業建議，不診斷個人，也不衡量個人價值。睡眠或健康問題應諮詢相應專業人士，而非依賴時間分配計算。"],["購買","Final Curtain Pro 透過 Apple 的一次性非消耗型購買解鎖「比較選擇」和主畫面小工具，無需訂閱。符合條件且已驗證的舊版小工具購買也可取得 Pro 權益。Apple 顯示目前商品與價格並處理付款。復原購買依賴相應 Apple 帳號及有效的 StoreKit 權益；已退款或撤銷的權益可能不再解鎖 Pro。復原購買不會復原已刪除的本機規劃資料。退款遵循 Apple 流程和適用法律；這些條款不限制強制性消費者權利。"],["本機資料","請保護裝置存取安全並了解備份設定。檔案只保存在目前裝置，不是 App 帳號。單項活動會立即刪除，包括完整左滑；清空清單和刪除檔案仍需確認。我們不保證復原已刪除的本機資料。"],["授權與智慧財產權","透過 App Store 下載的 App，除非 App Store Connect 已為你所在國家或地區指定自訂最終使用者授權協議，否則其 App 授權受 Apple 標準最終使用者授權協議約束。本條款補充適用的授權協議，並規範本 App 的功能、內容及付費權益（如有）。在該協議及本條款約束下，IDEASpike 授予你僅為預定用途使用本 App 的有限、個人且不可轉讓授權。App、軟體、設計及所提供內容的全部權利由 IDEASpike 及其授權方保留。"],["使用與可用性","請合法使用 App，輸入他人資訊時尊重其隱私。IDEASpike 可更新、暫停或停止功能。在法律允許的範圍內，App 按可用狀態提供，除本條款明確約定或法律要求外，不作出額外保證；對於依賴估算、產生的反思文字或服務中斷造成的間接或後果性損失，IDEASpike 不承擔責任。本條款不排除依法不得排除的責任或消費者權利。"],["更新與聯絡","更新條款會在本頁發布。App 問題或購買協助可聯絡 support@ideaspike.com。"]]}}')}}]);